INSERT INTO `health_assessment` VALUES (2, '刘爱国', '210102196001267626', '1960-01-26 00:00:00', 64, 0, '80.5', 'caution', 0, '二级护理等级', 1, '2023-10-10', '中州体检', 'https://java110-ai.oss-cn-beijing.aliyuncs.com/2024/10/af59dc76-0c01-4043-9706-b9ed1ec08984.pdf', '2024-10-10 01:07:42', '体检报告中心率、肝脏、胆囊、脾脏、肾脏、前列腺共6项指标提示异常，综合这些临床指标和数据分析：循环系统、消化系统存在隐患，其中循环系统有“中危”风险；消化系统部位有“低危”风险。', '{\"healthy\":60,\"caution\":30,\"risk\":10,\"danger\":0,\"severeDanger\":0}', '[{\"conclusion\":\"心率略快\",\"examinationItem\":\"心率\",\"result\":\"92 次/分\",\"referenceValue\":\"< 140\",\"unit\":\"次/分\",\"interpret\":\"心率稍高于理想范围，可能与情绪、活动或轻度心脏负担有关。\",\"advice\":\"建议心电图检查及定期监测心率，保持情绪稳定，适量运动。\"},{\"conclusion\":\"轻度脂肪肝可能\",\"examinationItem\":\"肝\",\"result\":\"形态大小正常，实质回声略粗糙\",\"referenceValue\":\"-\",\"unit\":\"-\",\"interpret\":\"肝脏实质回声略粗糙，提示可能有轻度脂肪肝，与饮食习惯、生活方式或遗传因素有关。\",\"advice\":\"建议调整饮食结构，减少高脂食物摄入，增加运动，定期检查肝脏情况。\"},{\"conclusion\":\"慢性胆囊炎可能\",\"examinationItem\":\"胆\",\"result\":\"胆囊壁毛糙\",\"referenceValue\":\"-\",\"unit\":\"-\",\"interpret\":\"胆囊壁毛糙，可能表示有慢性胆囊炎，可能与胆囊结石、感染或长期饮食不规律有关。\",\"advice\":\"建议进一步检查胆囊情况，保持规律饮食，避免高脂食物。\"},{\"conclusion\":\"脾轻度增大\",\"examinationItem\":\"脾\",\"result\":\"轻度增大\",\"referenceValue\":\"-\",\"unit\":\"-\",\"interpret\":\"脾脏轻度增大，可能与感染、血液系统疾病或自身免疫性疾病有关。\",\"advice\":\"建议进一步检查脾脏，以确定增大的原因，并采取相应的治疗措施。\"},{\"conclusion\":\"右肾小囊肿可能\",\"examinationItem\":\"肾\",\"result\":\"右肾下极见一大小约 5mm 的无回声区\",\"referenceValue\":\"-\",\"unit\":\"mm\",\"interpret\":\"右肾小囊肿，一般为良性病变，可能与肾小管憩室增多有关。\",\"advice\":\"建议定期监测囊肿大小，若无症状且囊肿不增大，可暂不处理。\"},{\"conclusion\":\"前列腺形态略增大\",\"examinationItem\":\"前列腺\",\"result\":\"形态略增大\",\"referenceValue\":\"-\",\"unit\":\"-\",\"interpret\":\"前列腺形态略增大，可能与前列腺增生有关，是老年男性常见病变。\",\"advice\":\"建议进行PSA检查以排除前列腺肿瘤，并定期检查前列腺情况。\"}]', '{\"breathingSystem\":100,\"digestiveSystem\":85,\"endocrineSystem\":90,\"immuneSystem\":95,\"circulatorySystem\":80,\"urinarySystem\":90,\"motionSystem\":100,\"senseSystem\":90}', '1', '2024-10-10 01:07:42', NULL, NULL, NULL);
INSERT INTO `health_assessment` VALUES (5, '张芳', '410182195309190744', '1953-09-19 00:00:00', 71, 1, '75.0', 'caution', 0, '三级护理等级', 1, '2023.10.10', '传智健康体检中心', 'https://hzhm-mlgb2.oss-cn-beijing.aliyuncs.com/2025/02/28/0b3d9d0e75c24c7f8f80585a00f89988.pdf', '2025-02-28 19:16:47', '体检报告中血红蛋白、血压、胆固醇、低密度脂蛋白、右耳听力、双下肢、视力、乙肝表面抗体、脾、右肾共10项指标提示异常。综合这些临床指标和数据分析：循环系统、泌尿系统、免疫系统存在隐患，其中循环系统有“中危”风险；泌尿系统、免疫系统部位有“低危”风险。', '{\"healthy\":60,\"caution\":30,\"risk\":10,\"danger\":0,\"severeDanger\":0}', '[{\"conclusion\":\"双下肢水肿\",\"examinationItem\":\"内科检查\",\"result\":\"双下肢轻微凹陷性水肿\",\"referenceValue\":\"无水肿\",\"unit\":\"-\",\"interpret\":\"双下肢水肿可能与心肾功能异常有关，需要进一步检查以确定具体原因。\",\"advice\":\"建议进行心肾功能检查，根据检查结果采取相应治疗措施。同时，避免长时间站立或久坐，定期抬高下肢以促进血液循环。\"},{\"conclusion\":\"视力下降\",\"examinationItem\":\"眼科检查\",\"result\":\"视力略有下降\",\"referenceValue\":\"正常视力\",\"unit\":\"-\",\"interpret\":\"视力下降可能与年龄、用眼习惯、眼部疾病等因素有关。\",\"advice\":\"建议定期复查视力，配戴合适的老花镜，并注意用眼卫生，避免长时间用眼。\"},{\"conclusion\":\"右耳听力下降\",\"examinationItem\":\"耳鼻喉科检查\",\"result\":\"右耳听力下降\",\"referenceValue\":\"正常听力\",\"unit\":\"-\",\"interpret\":\"听力下降可能与年龄、耳部疾病、噪音暴露等因素有关。\",\"advice\":\"建议耳鼻喉科进一步评估，并根据评估结果采取相应治疗措施。避免长时间暴露于高噪音环境中。\"},{\"conclusion\":\"血压偏高\",\"examinationItem\":\"一般科室检查\",\"result\":\"收缩压 145 mmHg，舒张压 90 mmHg\",\"referenceValue\":\"收缩压 < 140 mmHg，舒张压 < 90 mmHg\",\"unit\":\"mmHg\",\"interpret\":\"血压偏高可能与生活习惯、遗传因素、其他疾病等有关，长期高血压可能增加心脑血管疾病风险。\",\"advice\":\"建议定期监测血压，改善生活习惯（如低盐饮食、适量运动），必要时心内科随访并考虑药物治疗。\"},{\"conclusion\":\"血红蛋白略低\",\"examinationItem\":\"血常规检查\",\"result\":\"血红蛋白 110 g/l\",\"referenceValue\":\"120-160 g/l\",\"unit\":\"g/l\",\"interpret\":\"血红蛋白略低可能与营养不良、贫血等因素有关。\",\"advice\":\"建议增加富含铁质的食物摄入，如红肉、绿叶蔬菜等，并定期进行血常规检查以监测血红蛋白水平。\"},{\"conclusion\":\"胆固醇及低密度脂蛋白略高\",\"examinationItem\":\"生化检查\",\"result\":\"总胆固醇 6.2 mmol/L，低密度脂蛋白 4.0 mmol/L\",\"referenceValue\":\"总胆固醇 2.3-5.7 mmol/L，低密度脂蛋白 2.1-3.1 mmol/L\",\"unit\":\"mmol/L\",\"interpret\":\"胆固醇及低密度脂蛋白略高可能与饮食习惯、遗传因素等有关，长期高水平可能增加心脑血管疾病风险。\",\"advice\":\"建议饮食控制，减少高脂肪食物摄入，增加蔬菜水果摄入，并定期进行生化检查以监测血脂水平。\"},{\"conclusion\":\"乙肝表面抗体阴性\",\"examinationItem\":\"免疫检查\",\"result\":\"乙肝表面抗体 阴性\",\"referenceValue\":\"阳性（接种乙肝疫苗后）\",\"unit\":\"-\",\"interpret\":\"乙肝表面抗体阴性表示未接种过乙肝疫苗或疫苗接种效果不佳，可能增加乙肝病毒感染风险。\",\"advice\":\"建议接种乙肝疫苗以提高抵抗力。\"},{\"conclusion\":\"脾轻度增大\",\"examinationItem\":\"B超检查\",\"result\":\"脾轻度增大\",\"referenceValue\":\"正常大小\",\"unit\":\"-\",\"interpret\":\"脾轻度增大可能与感染、血液系统疾病、自身免疫性疾病等因素有关。\",\"advice\":\"建议进一步检查以确定具体原因，并根据检查结果采取相应治疗措施。\"},{\"conclusion\":\"右肾小囊肿可能\",\"examinationItem\":\"B超检查\",\"result\":\"右肾下极见一大小约 5mm 的无回声区\",\"referenceValue\":\"无囊肿\",\"unit\":\"-\",\"interpret\":\"右肾小囊肿可能是一种良性病变，但需要进一步检查以确定性质。\",\"advice\":\"建议定期进行肾脏B超检查以监测囊肿变化，如有必要，可考虑手术治疗。\"}]', '{\"breathingSystem\":90,\"digestiveSystem\":85,\"endocrineSystem\":90,\"immuneSystem\":80,\"circulatorySystem\":75,\"urinarySystem\":80,\"motionSystem\":90,\"senseSystem\":85}', '1', '2025-02-28 19:16:47', NULL, NULL, NULL);
